   [96]={next_id=97, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="尤加利顿时青筋暴起。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [97]={next_id=98, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="臭小子，你在耍我吗？你以为我不知道这里出现过使徒级修格尔，还差点把这座城市都给掀翻了！", msg_color="", msg_size=0, talker="尤加利", audio="", img="arts/ui/bg/story/storybg_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [98]={next_id=99, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="使徒级修格尔已经死了。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [99]={next_id=100, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那又如何？空天星链不也要继续运转吗？如果下次再有使徒级修格尔出现——", msg_color="", msg_size=0, talker="尤加利", audio="", img="arts/ui/bg/story/storybg_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [100]={next_id=101, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那就再一次全力消灭它，直到再也不会出现，直到空天星链停止运转。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [101]={next_id=102, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="所以，其实所谓的不危险的地方直到今天根本就不存在——你也知道这点，尤加利。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
